#[derive(Serialize, Deserialize)]
struct Order {
    id: String,
    #[serde(flatten)]
    extra: HashMap<String, Value>,   // every other key the document carries
}

impl Order {
    fn set(&mut self, name: impl Into<String>, v: Value) { self.extra.insert(name.into(), v); }
    fn get(&self, name: &str) -> Option<&Value>          { self.extra.get(name) }
    fn names(&self) -> impl Iterator<Item = &String>     { self.extra.keys() } // discoverable
}
